const request = require('request');

const options = {
  method: 'PATCH',
  url: 'https://api.procore.com/rest/v1.0/requisitions/%7Brequisition_id%7D/bulk_item_update',
  qs: {project_id: 'SOME_INTEGER_VALUE'},
  headers: {'content-type': 'application/json'},
  body: {
    requisition_items: [
      {
        id: 1001,
        item_type: 1001,
        work_completed_this_period: 1000,
        materials_presently_stored: 500,
        work_completed_retainage_retained_this_period: 0.22,
        materials_stored_retainage_currently_retained: 0.23,
        work_completed_retainage_released_this_period: 0.24,
        work_completed_this_period_quantity: 10,
        subcontractor_claimed_amount: 20.5,
        status: 'rejected',
        comment: 'This work was not yet completed'
      }
    ]
  },
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Patch,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/requisitions/%7Brequisition_id%7D/bulk_item_update?project_id=SOME_INTEGER_VALUE"),
    Content = new StringContent("{\"requisition_items\":[{\"id\":1001,\"item_type\":1001,\"work_completed_this_period\":1000,\"materials_presently_stored\":500,\"work_completed_retainage_retained_this_period\":0.22,\"materials_stored_retainage_currently_retained\":0.23,\"work_completed_retainage_released_this_period\":0.24,\"work_completed_this_period_quantity\":10,\"subcontractor_claimed_amount\":20.5,\"status\":\"rejected\",\"comment\":\"This work was not yet completed\"}]}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}
